query.text:

declare @key2 nvarchar(3000),@sUpdate nvarchar(4000);
select @key2 = @lookupKey + case when @val = '' then '' else ' and (@@fieldKey like N''' + dbo.ISWIFTFunctionReplaceSQLValue(@val) + '%'' or @@fieldName like N''' + dbo.ISWIFTFunctionReplaceSQLValue(@val) + '%'')' end
SET @sUpdate = 'UPDATE a SET ds_ntask = (SELECT STRING_AGG(b.ma_ntask, '' , '') FROM wfdmkhct b WHERE a.id = b.id) FROM #v a';
exec ISWIFTStoreTableLoading '@@table', '@@fieldKey', '@@fields', @@fieldOrder, '', '', '', 'CAST('''' AS VARCHAR(4000)) ds_ntask', N'@@key', @key2, @@filterKey, @sUpdate , @pageIndex, 10, @@admin, @@userId
